import { useState } from "react";

function App() {
  const [input, setInput] = useState("");
  const [messages, setMessages] = useState([]);

const runMiller = () => {
  setMessages([]);

  const socket = new WebSocket("ws://127.0.0.1:8000/ws/miller");

  socket.onopen = () => {
    // send as string (not parseInt)
    socket.send(JSON.stringify({ n: input }));
  };

  socket.onmessage = (event) => {
    setMessages((prev) => [...prev, event.data]);
  };
};

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-gradient-to-br from-indigo-500 to-purple-700 text-white p-6">
      <h1 className="text-3xl font-bold mb-6">Miller-Rabin Primality Test</h1>

      <input
        type="number"
        placeholder="Enter number"
        value={input}
        onChange={(e) => setInput(e.target.value)}
        className="text-black p-2 rounded mb-4 w-64"
      />
      <button
        onClick={runMiller}
        className="bg-yellow-400 hover:bg-yellow-500 text-black px-4 py-2 rounded font-semibold"
      >
        Run Test
      </button>

      <div className="mt-6 bg-white text-black rounded-lg shadow-lg p-4 w-96 max-h-80 overflow-y-auto">
        {messages.map((msg, i) => (
          <div key={i} className="mb-2">
            ➤ {msg}
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
